WITH q AS (SELECT cat.category_id,cat.category_name,cat.description,COUNT(c.complaint_id)::int AS complaint_count FROM dropboxed.complaint_categories cat LEFT JOIN dropboxed.complaints c ON c.category_id=cat.category_id GROUP BY cat.category_id ORDER BY cat.category_id) SELECT jsonb_build_object('rows',count(*),'md5',md5(COALESCE(string_agg(to_jsonb(q)::text,E'\n' ORDER BY to_jsonb(q)::text),''))) FROM q;
